mapper.sql:
SELECT f.id, f.preparation_id, f.input_revision, f.file_name, f.media_type, f.file_bytes, f.source_sha256, f.placements_json, f.generator_version, f.generation_fingerprint
FROM application_document_file f JOIN application_preparation p ON p.id = f.preparation_id
WHERE p.owner_account_id = #{ownerId} AND p.id = #{preparationId}
